/* CSS Variables */
:root {
    --primary-black: #000000;
    --accent-purple: #7638FA;
    --accent-orange: #FF7A00;

    --bg-light: #FFFFFF;
    --bg-soft-purple: #F5F1FF;
    --bg-soft-orange: #FFF5EE;
    --bg-gray: #F8F9FA;

    --text-primary: #111111;
    --text-secondary: #555555;

    --border-color: #E5E5E5;

    --radius-lg: 32px;
    --radius-md: 24px;
    --radius-sm: 12px;

    --transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
    --shadow-sm: 0 4px 12px rgba(0,0,0,0.05);
    --shadow-lg: 0 24px 48px rgba(0,0,0,0.1);
}

/* Reset & Typography */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Plus Jakarta Sans', sans-serif;
    color: var(--text-primary);
    background-color: var(--bg-light);
    line-height: 1.5;
    overflow-x: hidden;
}

h1, h2, h3, h4 {
    line-height: 1.2;
    font-weight: 700;
    letter-spacing: -0.02em;
}

a {
    text-decoration: none;
    color: inherit;
}

ul {
    list-style: none;
}

.container {
    width: 100%;
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 24px;
}

.section-padding {
    padding: 96px 0;
}

/* Header */
.site-header {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 100;
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border-color);
}

.header-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 72px;
}

.logo {
    font-size: 24px;
    font-weight: 800;
    background: linear-gradient(135deg, var(--accent-purple), var(--accent-orange));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    letter-spacing: -0.04em;
}

.menu-toggle, .menu-close {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--primary-black);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 8px;
}

.btn-login {
    font-weight: 600;
    padding: 10px 24px;
    border-radius: var(--radius-sm);
    background: var(--bg-gray);
    color: var(--primary-black);
    transition: var(--transition);
}

.btn-login:hover {
    background: #e2e2e2;
}

/* Navigation Overlay */
.nav-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100vh;
    background: var(--bg-light);
    z-index: 200;
    display: flex;
    flex-direction: column;
    transform: translateY(-100%);
    transition: transform 0.4s cubic-bezier(0.8, 0, 0.2, 1);
    opacity: 0;
    pointer-events: none;
}

.nav-overlay.active {
    transform: translateY(0);
    opacity: 1;
    pointer-events: auto;
}

.nav-overlay-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 72px;
    border-bottom: 1px solid var(--border-color);
}

.nav-overlay-body {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.mobile-nav-list {
    text-align: center;
}

.mobile-nav-list li {
    margin: 32px 0;
}

.mobile-nav-list a {
    font-size: 32px;
    font-weight: 700;
    transition: var(--transition);
}

.mobile-nav-list a:hover {
    color: var(--accent-purple);
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    border-radius: var(--radius-sm);
    transition: var(--transition);
}

.btn-primary {
    background: var(--primary-black);
    color: white;
}

.btn-primary:hover {
    background: #333;
    transform: translateY(-2px);
}

.btn-large {
    padding: 16px 40px;
    font-size: 18px;
    border-radius: 40px;
}

/* Hero Section */
.hero-section {
    position: relative;
    padding: 160px 0 120px;
    text-align: center;
    overflow: hidden;
}

.hero-bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    opacity: 0.15;
    filter: blur(80px);
}

.blob {
    position: absolute;
    border-radius: 50%;
}

.blob-purple {
    width: 400px;
    height: 400px;
    background: var(--accent-purple);
    top: -100px;
    left: 20%;
}

.blob-orange {
    width: 350px;
    height: 350px;
    background: var(--accent-orange);
    bottom: -50px;
    right: 20%;
}

.hero-content {
    max-width: 900px;
}

.hero-title {
    font-size: clamp(40px, 6vw, 72px);
    margin-bottom: 24px;
}

.hero-subtitle {
    font-size: clamp(18px, 2vw, 24px);
    color: var(--text-secondary);
    margin-bottom: 48px;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

/* Layout Utilities */
.grid-50 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 64px;
    align-items: center;
}

.bg-soft-purple { background-color: var(--bg-soft-purple); }
.bg-soft-orange { background-color: var(--bg-soft-orange); }

/* Feature Sections */
.feature-text {
    max-width: 500px;
}

.feature-reverse .feature-text {
    order: 2;
}

.feature-reverse .feature-visual {
    order: 1;
}

.section-title {
    font-size: clamp(32px, 4vw, 48px);
    margin-bottom: 24px;
}

.section-desc {
    font-size: 18px;
    color: var(--text-secondary);
    margin-bottom: 32px;
}

.text-link {
    font-size: 18px;
    font-weight: 700;
    color: var(--accent-purple);
    display: inline-flex;
    align-items: center;
    transition: var(--transition);
}

.text-link:hover {
    gap: 8px;
    color: var(--accent-orange);
}

/* Mockups */
.visual-card {
    background: white;
    border-radius: var(--radius-lg);
    overflow: hidden;
    height: 500px;
    position: relative;
}

.mockup-ui {
    width: 100%;
    height: 100%;
    background-size: cover;
    background-position: center;
    position: relative;
}

.mockup-features {
    background: linear-gradient(135deg, #FFC371 0%, #FF5F6D 100%);
    border-radius: var(--radius-lg);
}

.mockup-safety {
    background: linear-gradient(135deg, #A8CABA 0%, #5D4157 100%);
    border-radius: var(--radius-lg);
}

.mockup-creators {
    background: linear-gradient(135deg, #7F00FF 0%, #E100FF 100%);
    border-radius: var(--radius-lg);
}

/* Tagline Banner */
.tagline-banner {
    background: var(--primary-black);
    color: white;
    padding: 80px 0;
    text-align: center;
}

.tagline-text {
    font-size: clamp(28px, 4vw, 40px);
    font-weight: 600;
}

/* News Section */
.news-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 48px;
}

.news-label {
    font-size: 14px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent-purple);
    display: block;
    margin-bottom: 8px;
}

.news-title {
    font-size: clamp(28px, 4vw, 40px);
}

.btn-view-more {
    font-weight: 600;
    color: var(--text-primary);
    text-decoration: underline;
    text-underline-offset: 4px;
}

.carousel-container {
    width: 100%;
    overflow: hidden;
}

.news-carousel {
    display: flex;
    gap: 24px;
    padding: 0 24px 32px; /* Bottom padding for scrollbar */
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scrollbar-width: none; /* Firefox */
    -ms-overflow-style: none;  /* IE and Edge */
}

.news-carousel::-webkit-scrollbar {
    display: none; /* Chrome, Safari and Opera */
}

.news-card {
    flex: 0 0 320px;
    scroll-snap-align: start;
    display: flex;
    flex-direction: column;
    gap: 16px;
    cursor: pointer;
}

.card-thumb {
    width: 100%;
    height: 200px;
    border-radius: var(--radius-md);
    background: var(--bg-gray);
}

.thumb-1 { background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%); }
.thumb-2 { background: linear-gradient(135deg, #ff9a9e 0%, #fecfef 99%, #fecfef 100%); }
.thumb-3 { background: linear-gradient(135deg, #f6d365 0%, #fda085 100%); }
.thumb-4 { background: linear-gradient(135deg, #84fab0 0%, #8fd3f4 100%); }

.tags {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.tag {
    font-size: 10px;
    font-weight: 700;
    padding: 4px 8px;
    border-radius: 4px;
}

.tag-purple { background: #F0E6FF; color: var(--accent-purple); }
.tag-orange { background: #FFF0E5; color: var(--accent-orange); }
.tag-black { background: #F0F0F0; color: var(--primary-black); }

.card-title {
    font-size: 18px;
    font-weight: 700;
    line-height: 1.4;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.card-date {
    font-size: 14px;
    color: var(--text-secondary);
    margin-top: auto;
}

/* CTA Download */
.cta-download {
    text-align: center;
    background: var(--bg-gray);
}

.cta-title {
    font-size: clamp(32px, 5vw, 56px);
    margin-bottom: 8px;
}

.cta-subtitle {
    font-size: 24px;
    color: var(--text-secondary);
    margin-bottom: 40px;
}

.store-buttons {
    display: flex;
    justify-content: center;
    gap: 16px;
}

.btn-store {
    background: white;
    border: 1px solid var(--border-color);
    padding: 16px 32px;
    font-size: 16px;
    color: var(--primary-black);
    border-radius: var(--radius-lg);
}

.btn-store:hover {
    background: var(--bg-gray);
    border-color: #ccc;
}

/* Footer */
.site-footer {
    padding: 80px 0 40px;
    background: white;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 40px;
    margin-bottom: 80px;
}

.footer-heading {
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 24px;
}

.footer-links li {
    margin-bottom: 12px;
}

.footer-links a {
    color: var(--text-secondary);
    font-size: 14px;
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--accent-purple);
}

.footer-bottom {
    border-top: 1px solid var(--border-color);
    padding-top: 32px;
}

.footer-bottom-content {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
}

.language-select select {
    padding: 8px 32px 8px 16px;
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    background: white;
    font-family: inherit;
    font-size: 14px;
    appearance: none;
    background-image: url('data:image/svg+xml;utf8,<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 9l6 6 6-6"/></svg>');
    background-repeat: no-repeat;
    background-position: right 12px center;
    cursor: pointer;
}

.social-links {
    display: flex;
    gap: 16px;
}

.social-links a {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: var(--bg-gray);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 700;
    color: var(--text-primary);
    transition: var(--transition);
}

.social-links a:hover {
    background: var(--primary-black);
    color: white;
}

.legal-links {
    font-size: 14px;
    color: var(--text-secondary);
}

.legal-links a {
    margin: 0 4px;
}

.legal-links a:hover {
    text-decoration: underline;
}

.copyright {
    font-size: 14px;
    color: var(--text-secondary);
}

/* Responsive */
@media (max-width: 991px) {
    .grid-50 {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .feature-reverse .feature-text {
        order: unset;
    }

    .feature-reverse .feature-visual {
        order: unset;
    }

    .visual-card {
        height: 400px;
    }
}

@media (max-width: 768px) {
    .section-padding {
        padding: 64px 0;
    }

    .news-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 16px;
    }

    .footer-bottom-content {
        flex-direction: column;
        align-items: flex-start;
    }

    .store-buttons {
        flex-direction: column;
        width: 100%;
        max-width: 300px;
        margin: 0 auto;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const menuToggle = document.getElementById('menuToggle');
    const menuClose = document.getElementById('menuClose');
    const navOverlay = document.getElementById('navOverlay');
    const navLinks = document.querySelectorAll('.mobile-nav-list a');

    // Open Menu
    menuToggle.addEventListener('click', (e) => {
        e.preventDefault();
        navOverlay.classList.add('active');
        document.body.style.overflow = 'hidden'; // Prevent scrolling
    });

    // Close Menu
    menuClose.addEventListener('click', (e) => {
        e.preventDefault();
        navOverlay.classList.remove('active');
        document.body.style.overflow = '';
    });

    // Close Menu when clicking a link
    navLinks.forEach(link => {
        link.addEventListener('click', () => {
            navOverlay.classList.remove('active');
            document.body.style.overflow = '';
        });
    });
});
